import React from 'react';
import ReactDOM from 'react-dom';
import { Form, Input, Icon } from '@alifd/next';

const { Item: FormItem } = Form;

// 业务层对 FormItem 的二次封装，给 label 添加了 Icon
const BizFormItem = props => {
  const { label, children, ...others } = props;
  return (
    <FormItem
      label={
        <span>
          {label}
          <Icon type="help" size="small" />
        </span>
      }
      {...others}
    >
      {children}
    </FormItem>
  );
};

class Demo extends React.Component {
  // 通过 Form 自动关联 Field
  field = new Form.Field(this);

  handleSubmit = (values, errors) => {
    console.log('values:', values);
    console.log('errors:', errors);
  };

  render() {
    const { init } = this.field;
    return (
      <Form
        field={this.field}
        useLabelForErrorMessage  // 开启 label 替换错误名
        onSubmit={this.handleSubmit}
        style={{ maxWidth: 400, margin: '20px auto' }}
      >
        <BizFormItem label="Account" required name="valUsername">
          <Input
            {...init('valUsername', {
              rules: [{ required: true }]
            })}
            placeholder="请输入 Account"
          />
        </BizFormItem>
        <Form.Submit validate type="primary">
          Submit
        </Form.Submit>
      </Form>
    );
  }
}

ReactDOM.render(<Demo />, mountNode);

// 执行后点击 Submit，错误提示会显示 “valUsername is required” 而不是预期的 “Account is required”。
